for (const ch of ['J','I','G']) {
  const v = src.replace(`j.region.text('JIG', { size: mm(10) })`, `j.region.text('${ch}', { size: mm(10) })`);
  const r = await check(v);
  out[ch] = { vol: r.metrics.volume, faces: r.metrics.faces };
}
return out;

